def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    ops = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # earliest[j] = smallest operation index (1-based) where j bananas can be created
    earliest = [-1] * (m + 1)
    earliest[0] = 0

    # current_reachable = set of banana counts after current operation
    current_reachable = {0}

    for op_idx in range(1, n + 1):
        t, x, y = ops[op_idx - 1]
        next_reachable = set()

        for k in sorted(current_reachable):
            if k > m:
                continue

            if t == 1:
                # Type 1: k := ceil(k + x) applied a times
                # ceil(k + a*x) = floor(k + a*x - epsilon) but k, x might be fractional
                # We'll use floating point and then ceil
                for a in range(y + 1):
                    val = ceil(k + a * x)
                    if val <= m:
                        next_reachable.add(val)
            else:
                # Type 2: k := ceil(k * x) applied a times
                # Repeatedly apply: k = ceil(k * x)
                temp_k = k
                for a in range(y + 1):
                    val = ceil(temp_k * x)
                    if val <= m:
                        next_reachable.add(val)
                    else:
                        break
                temp_k = k  # for next iteration we start fresh, not cumulative within this op iteration

        earliest[0] = 0  # 0 bananas is always achievable from start

        for val in next_reachable:
            if earliest[val] == -1:
                earliest[val] = op_idx

        current_reachable = next_reachable

    return ' '.join(map(str, earliest[1:])) + '\n'

def ceil(x):
    if x == int(x):
        return int(x)
    return int(x) + 1

