def solution(input_str):
    # Parse the input string
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    line_idx = 1

    results = []
    for _ in range(t):
        # Read n and m
        n, m = map(int, lines[line_idx].split())
        line_idx += 1

        # Calculate XOR sum of all non-zero values
        xor_sum = 0
        for i in range(n):
            row = list(map(int, lines[line_idx].split()))
            line_idx += 1
            for val in row:
                if val > 0:
                    xor_sum ^= val

        # If XOR sum is non-zero, first player (Ashish) wins
        # Otherwise, second player (Jeel) wins
        if xor_sum != 0:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

import sys
from collections import deque

sys.setrecursionlimit(100000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    roads = []
    for i in range(m):
        parts = lines[2 + i].split()
        x, y, w = map(int, parts)
        roads.append((x, y, w, i + 1))

    graph = [[] for _ in range(n + 1)]
    for i, (x, y, w, idx) in enumerate(roads):
        graph[x].append((y, w, idx))
        graph[y].append((x, w, idx))

    def bfs_distances(start, ignore_edge=None):
        """Return distances from start node using BFS, ignoring an optional edge (u, v, idx)"""
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            if u == t:
                break
            for v, w, idx in graph[u]:
                if (ig_u, ig_v, ig_idx) := (ignore_edge[0], ignore_edge[1], ignore_edge[2]):
                    if u == ig_u and v == ig_v and idx == ig_idx:
                        continue
                    if dist[v] == -1:
                        dist[v] = dist[u] + w  # BFS here just counts reachability correctly
                        queue.append(v)
        return dist

    def can_reach_exists(start, end, ignore_edge=None):
        """Check if end is reachable from start given edges to ignore"""
        visited = [False] * (n + 1)
        visited[start] = True
        queue = deque([start])
        while queue:
            u = queue.popleft()
            if u == end:
                return True
            for v, w, idx in graph[u]:
                if ignore_edge and idx == ignore_edge[2] and (u == ignore_edge[0] or v == ignore_edge[1]):
                    continue
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return visited[end]

    def bfs_no_road():
        """Check connectivity without ignoring any roads"""
        visited = [False] * (n + 1)
        visited[s] = True
        queue = deque([s])
        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, _, _ in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return visited[t]

    if not bfs_no_road():
        return "0\n0\n"

    # Case 1: 0 roads removed - already disconnected, cost 0
    # Case 2: 1 road removed - find minimum weight edge on all paths

    # Simple BFS-based solution
    INF = 2 * 10**9
    min_cost_1 = INF
    min_cost_2 = INF

    # Try removing 1 edge
    for idx in range(m):
        x, y, w, _ = roads[idx]
        if not can_reach_exists(s, t, ignore_edge=(x, y, idx + 1)):
            if w < min_cost_1:
                min_cost_1 = w

    # If we have a solution with 1 edge, check if 2 edges gives better
    if min_cost_1 != INF:
        best_cost_2 = min_cost_1
    else:
        best_cost_2 = INF

    # Answer is either 0 (if disconnected), or min(min_cost_1, min_cost_2)
    ans = 0
    count_ans = 0
    edges_ans = ""

    if min_cost_1 != INF:
        ans = min_cost_1
        count_ans = 1
        edges_ans = roads[0][3] if roads[0][1] in [(roads[k][0], roads[k][1]) or (roads[k][1], roads[k][0]) for k in range(m)] else "-"
        # Find actual edge index
        for i in range(m):
            x, y, val, idx = roads[i]
            if val == min_cost_1 and i < m:
                ans = min_cost_1
                if ans != 0:
                    count_ans = 1
                    edges_ans = str(idx)
                break

    if best_cost_2 != INF and best_cost_2 < ans:
        ans = best_cost_2
        count_ans = 2
        # Find two edges
        min1 = INF
        min2 = INF
        idx1, idx2 = -1, -1
        for idx in range(m):
            x, y, w, i_idx = roads[idx]
            if not can_reach_exists(s, t, ignore_edge=(x, y, i_idx)):
                if w < min1:
                    min2 = min1
                    idx2 = idx1
                    min1 = w
                    idx1 = idx
                elif w < min2:
                    min2 = w
                    idx2 = idx
        if min1 != INF and idx1 != -1 and idx2 != -1:
            ans = w + idx1
            # Find the best pair
            ans = INF
            for i in range(m):
                for j in range(i + 1, m):
                    idx1, idx2 = i, j
                    if not (can_reach_exists(s, t, ignore_edge=(roads[idx1][0], roads[idx1][1], roads[idx1][3])) or
                            can_reach_exists(s, t, ignore_edge=(roads[j][0], roads[j][1], roads[j][3]))):
                        w_sum = roads[idx1][2] + roads[idx2][2]
                        if w_sum < ans:
                            ans = w_sum
                            count_ans = 2
                            edges_ans = f"{roads[idx1][3]} {roads[idx2][3]}"

    if count_ans == 2:
        return f"{ans}\n2\n{edges_ans}"
    elif count_ans == 1:
        return f"{ans}\n1\n{edges_ans}"
    elif ans == 0:
        return "0\n0\n"
    else:
        return "-1"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n == 0:
        return '\n'

    competitors = []
    for i in range(n):
        parts = lines[i + 1].split()
        if len(parts) >= 2:
            s, r = int(parts[0]), int(parts[1])
        else:
            s, r = 1, 1
        competitors.append((s, r, i + 1))

    ans = []

    for i in range(n):
        si, ri, idx = competitors[i]
        is_possible = True

        # Check if person i is dominated by any other competitor j
        # Person j dominates i if: s_j >= s_i and r_j >= r_i
        # (at least one inequality must be strict)
        for j in range(n):
            if i == j:
                continue
            sj, rj, _ = competitors[j]

            if sj >= si and rj >= ri:
                if sj > si or (sj == si and rj > ri):
                    is_possible = False
                    break

        if is_possible:
            ans.append(idx)

    # Sort the results in increasing order and format as required
    ans.sort()
    result = ' '.join(map(str, ans))
    return result + '\n'

