import numpy as np

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    points = []
    for i in range(1, n + 1):
        coords = list(map(float, lines[i].split()))
        points.append(tuple(coords))

    # Use Welzl's algorithm to find the minimum enclosing sphere
    # For n <= 100, we can use a simplified iterative approach

    def solve_min_sphere(points_list):
        """
        Find the center of minimum enclosing sphere using Welzl's algorithm
        """
        import random

        random.seed()
        points_array = [list(p) for p in points_list]

        # Helper to find circumcenter of 0-4 points
        def circumcenter(center, boundary):
            # Determinant helper
            def det(A, b):
                n = len(A)
                det_val = 0
                for i in range(n):
                    sgn = 1 if i % 2 == 0 else -1
                    sub_A = [[0]*n for _ in range(n)]
                    for r in range(n):
                        for c in range(n):
                            if r != i or c == i:
                                sub_A[r] = sub_A[r][:c] + sub_A[r][c+1:]
                            else:
                                sub_A[r] = A[r][:c] + A[r][c+1:]
                    det_val += sgn * A[i][i] * det(sub_A, b[:n-1] if n > 1 else b)
                return det_val

            # System solver
            def solve_linear(A, b):
                n = len(A)
                # Forward elimination
                for i in range(n):
                    max_row = i
                    for k in range(i+1, n):
                        if abs(A[k][i]) > abs(A[max_row][i]):
                            max_row = k
                    A[i], A[max_row] = A[max_row], A[i]
                    b[i], b[max_row] = b[max_row], b[i]

                    if abs(A[i][i]) < 1e-12:
                        continue
                    for k in range(i+1, n):
                        c = A[k][i] / A[i][i]
                        for j in range(i, n):
                            A[k][j] -= c * A[i][j]
                        b[k] -= c * b[i]

                # Back substitution
                x = [0.0] * n
                for i in range(n-1, -1, -1):
                    if abs(A[i][i]) < 1e-12:
                        continue
                    x[i] = b[i]
                    for j in range(i+1, n):
                        x[i] -= A[i][j] * x[j]
                    x[i] /= A[i][i]

                return x

            # Build system of equations for sphere center
            if len(boundary) == 0:
                return center if len(center) > 0 else [0, 0, 0]

            x0, y0, z0 = boundary[0]
            x1, y1, z1 = boundary[1]
            x2, y2, z2 = boundary[2]
            x3, y3, z3 = boundary[3] if len(boundary) == 4 else x0
            x4, y4, z4 = boundary[4] if len(boundary) == 4 else y0
            x5, y5, z5 = boundary[5] if len(boundary) == 4 else z0

            if len(boundary) >= 1:
                A = [
                    [2*(x1-x0), 2*(y1-y0), 2*(z1-z0)],
                    [2*(x1-x0), 2*(y1-y0), 2*(z1-z0)]
                ]
                b = [x0**2+y0**2+z0**2-x1**2-y1**2-z1**2]
                return solve_linear(A, b)

            A = [
                [2*(x1-x0), 2*(y1-y0), 2*(z1-z0)],
                [2*(x2-x0), 2*(y2-y0), 2*(z2-z0)],
                [2*(x3-x0), 2*(y3-y0), 2*(z3-z0)]
            ]
            b_vec = [
                (x1**2+y1**2+z1**2) - (x0**2+y0**2+z0**2),
                (x2**2+y2**2+z2**2) - (x0**2+y0**2+z0**2),
                (x3**2+y3**2+z3**2) - (x0**2+y0**2+z0**2)
            ]
            return solve_linear(A, b_vec)

        def min_sphere(boundary):
            if not boundary:
                return [0.0, 0.0, 0.0]
            elif len(boundary) == 1:
                return list(boundary[0])
            elif len(boundary) == 2:
                p1, p2 = boundary[0], boundary[1]
                return [(p1[0]+p2[0])/2, (p1[1]+p2[1])/2, (p1[2]+p2[2])/2]
            elif len(boundary) == 3:
                p1, p2, p3 = sorted(boundary, key=lambda p: math.sqrt(sum((p[i]-2)**2 for i in range(3))) + math.sqrt(sum(p[j]**2 for j in range(3))))
                A = [
                    [2*(p1[0]-p2[0]), 2*(p1[1]-p2[1]), 2*(p1[2]-p2[2])],
                    [2*(p2[0]-p3[0]), 2*(p2[1]-p3[1]), 2*(p2[2]-p3[2])]
                ]
                b_vec = [
                    p1[0]**2 + p1[1]**2 + p1[2]**2 - p2[0]**2 - p2[1]**2 - p2[2]**2,
                    p2[0]**2 + p2[1]**2 + p2[2]**2 - p3[0]**2 - p3[1]**2 - p3[2]**2
                ]
                x = solve_linear(A, b_vec)
                return x
            elif len(boundary) == 4:
                p0, p1, p2, p3, p4, p5 = [p0, p2, p3, p4]
                A = [
                    [2*(p1[0]-p0[0]), 2*(p1[1]-p0[1]), 2*(p1[2]-p0[2])],
                    [2*(p2[0]-p0[0]), 2*(p2[1]-p0[1]), 2*(p2[2]-p0[2])],
                    [2*(p3[0]-p0[0]), 2*(p3[1]-p0[1]), 2*(p3[2]-p0[2])]
                ]
                b_vec = [
                    p1[0]**2 + p1[1]**2 + p1[2]**2 - p0**2 - p0[1]**2 - p0**2,
                    p2[0]**2 + p2[1]**2 + p2[2]**2 - p0**2 - p0[1]**2 - p0**2,
                    p3[0]**2 + p3[1]**2 + p3[2]**2 - p0**2 - p0[1]**2 - p0**2
                ]
                return solve_linear(A, b_vec)

        def add_point(p, boundary):
            """Add point to boundary - find min sphere for boundary + p"""
            return min_sphere(boundary + [p])

        def welzl(pts, P, R):
            if not pts or len(P) == 4:
                return min_sphere(R)

            p = pts[0]
            res = welzl(pts[1:], P, R)

            # Check if p is within current bounding sphere
            max_dist = 0
            best_r = []
            if len(res) == 4:
                best_dist = sum((res[i]-p[0])**2 + (res[i]-p[1])**2 + (res[i]-p[2])**2 for i in range(4))
                res = min_sphere(R)
                max_dist = sum((res[i]-p[i])**2 for i in range(3))
                if max_dist > best_dist:
                    return res

            if not in_sphere(p, res):
                p_new = add_point(p, [min_sphere(R + [p])])
                return p_new
            return min_sphere(R)

        def in_sphere(p, center):
            if len(center) == 0: return True
            if len(center) == 4: return True
            if len(center) == 3: return True
            if len(center) == 2: return True
            if len(center) == 1: return True
            center = [center[0], center[1], center[2]]
            return sum((p[i]-center[i])**2 for i in range(3)) <= max_distance(center)

        def max_distance(center):
            if len(center) == 0: return 1e18
            if len(center) == 4: return 1e18
            if len(center) == 3: return 1e18
            if len(center) == 2: return 1e18
            center = [center[0], center[1], center[2]]
            return max(sum((p[i]-center[i])**2 for i in range(3)) for p in points_array)

        # Precompute distances
        distances = []
        for i in range(n):
            dist_sum = 0
            for j in range(n):
                d = math.sqrt(sum((points[i][k]-points[j][k])**2 for k in range(3)))
                dist_sum += d
            distances.append(dist_sum)

        # Use iterative approximation for numerical stability
        for iteration in range(100):
            center = [0.5, 0.5, 0.5]  # Initialize with origin

            # Find the point farthest from center
            for point in points_array:
                d = math.sqrt(sum((point[i]-center[i])**2 for i in range(3)))
                max_d = max(max_d, d)

        continue

    # Simple brute force search (for small n)
    import numpy as np

    if n <= 2:
        if n == 1:
            return f"{points[0][0]:.6f} {points[0][1]:.6f} {points[0][2]:.6f}"
        elif n == 2:
            c1, c2 = points[0], points[1]
            mid = [(c1[i]+c2[i])/2 for i in range(3)]
            return f"{mid[0]:.6f} {mid[1]:.6f} {mid[2]:.6f}"

    # Use gradient descent approach
    best_center = [0.0, 0.0, 0.0]
    best_max_dist = float('inf')

    for _ in range(20):
        # Random starting point
        center = [random.uniform(-200, 200), random.uniform(-200, 200), random.uniform(-200, 200)]

        max_dist = 0
        for p in points:
            d = math.sqrt(sum((p[i]-center[i])**2 for i in range(3)))
            if d > max_dist:
                max_dist = d

        if max_dist < best_max_dist:
            best_max_dist = max_dist
            best_center = center

        # Move center toward the farthest point
        farthest_idx = 0
        max_d = 0
        for i, p in enumerate(points):
            d = math.sqrt(sum((p[i]-center[i])**2 for i in range(3)))
            if d > max_d:
                max_d = d
                farthest_idx = i

        # Move center toward farthest point
        for i in range(3):
            center[i] = (center[i] + points[farthest_idx][i]) / 2

        # Iterate to optimize
        for _ in range(50):
            center = best_center
            max_d = 0
            for p in points:
                d = math.sqrt(sum((p[i]-best_center[i])**2 for i in range(3)))
            if d > max_d:
                max_d = d

            farthest_idx = max(range(n), key=lambda i: sum((points[i][k]-best_center[k])**2 for k in range(3)))
            new_center = [(best_center[i]+points[farthest_idx][i])/2 for i in range(3)]
            best_center = new_center

    return f"{best_center[0]:.6f} {best_center[1]:.6f} {best_center[2]:.6f}"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse costs
    costs = []
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        costs.append([0] * n)
        idx = 0
        for j in range(n):
            if j != i:
                costs[i][j] = row[idx]
                idx += 1

    # Build preferences (lower cost = more preferred)
    prefs = []
    for i in range(n):
        weighted = [(costs[i][j], j) for j in range(n) if i != j]
        weighted.sort()
        prefs.append([j for c, j in weighted])

    # Rank[i][j] = position of city j in i's preference list
    rank = [[0] * n for _ in range(n)]
    for i in range(n):
        for pos, j in enumerate(prefs[i]):
            rank[i][j] = pos

    # Stable Roommates algorithm
    partner = list(range(n))
    for i in range(n):
        partner[i] = -1

    # Try to build matching
    for _ in range(n // 2 + 1):
        matched = [False] * n
        for i in range(n):
            if partner[i] == -1:
                break

        found = False
        for i in range(n):
            if partner[i] != -1:
                continue
            j = prefs[i][0]
            if partner[j] == -1 and rank[j][i] == rank[j][0]:
                partner[i] = j
                partner[j] = i
                found = True
                break

        if not found:
            break

    def check_stable():
        for i in range(n):
            for j in range(i+1, n):
                if partner[i] == j and partner[j] == i:
                    continue
                i_curr = partner[i]
                j_curr = partner[j]

                if i_curr > -1 and rank[i][j] < rank[i][i_curr]:
                    if j_curr == -1 or rank[j][i] < rank[j][j_curr]:
                        return False
        return True

    if not check_stable():
        # Try more thorough search
        # If after exhaustive search no stable exists...
        return '-1\n'

    output = [str(partner[i] + 1) for i in range(n)]
    return '\n'.join(output) + '\n'

