def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])
    grid = [list(lines[i + 1]) for i in range(n)]

    def is_filled_in_rrcc_grid(grid, r, c):
        """Checks if cells in grid[r][c] are filled in the current state"""
        return grid[r][c] == '.'

    def get_component(grid, r, c):
        """Returns connected component of '.' starting at (r, c) via BFS"""
        component = []
        queue = [(r, c)]
        while queue:
            curr_r, curr_c = queue.pop(0)
            if (curr_r, curr_c) in component:
                continue
            component.append((curr_r, curr_c))

            # Check 4 neighbors
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if grid[nr][nc] == '.' and (nr, nc) not in component:
                        queue.append((nr, nc))
        return component

    def get_bounding_box(component):
        """Returns (min_r, max_r, min_c, max_c) for a component"""
        if not component:
            return None

        min_r, max_r = float('inf'), float('-inf')
        min_c, max_c = float('inf'), float('-inf')

        for r, c in component:
            min_r = min(min_r, r)
            max_r = max(max_r, r)
            min_c = min(min_c, c)
            max_c = max(max_c, c)

        return min_r, max_r, min_c, max_c

    # Main iterative approach
    changed = True
    iterations = 0
    max_iterations = n * m + 10  # Safety limit

    while changed and iterations < max_iterations:
        changed = False
        iterations += 1
        visited = [[False] * m for _ in range(n)]

        # First pass: find all components and fill their bounding boxes
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.' and not visited[r][c]:
                    component = get_component(grid, r, c)

                    # Calculate bounding box
                    box = get_bounding_box(component)
                    if box:
                        min_r, max_r, min_c, max_c = box

                        # Fill the bounding box with '.'
