    """
    Solves the Hiasat handle problem by finding the maximum number of happy friends.
    Friends conflict if they appear together in the same segment (between two type 1 events).
    We use a Maximum Independent Set approach with meet-in-the-middle.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    name_to_id = {}
    id_counter = 0

    segments = []
    current_seg = []

    # Parse events and group into segments
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if parts[0] == '1':
            if current_seg:
                segments.append(current_seg)
                current_seg = []
        else:
            friend_name = parts[1]
            if friend_name not in name_to_id:
                name_to_id[friend_name] = id_counter
                id_counter += 1
            current_seg.append(name_to_id[friend_name])
    if current_seg:
        segments.append(current_seg)

    # Build conflict graph: two friends conflict if they appear in same segment
    adj = [0] * id_counter
    for seg in segments:
        sz = len(seg)
        for i in range(sz):
            for j in range(i + 1, sz):
                u, v = seg[i], seg[j]
                adj[u] |= (1 << v)
                adj[v] |= (1 << u)

    # Use meet-in-the-middle to solve Maximum Independent Set
    half = id_counter // 2

    # Generate all valid independent subset masks for first half
    first_valid = []

    def dfs(idx, mask):
        if idx == half:
            first_valid.append(mask)
            return
        dfs(idx + 1, mask)  # Don't include
        if not (mask & adj[idx]):
            dfs(idx + 1, mask | (1 << idx))  # Include if no conflict

    dfs(0, 0)

    ans = 0

    for first_mask in first_valid:
        cnt1 = bin(first_mask).count('1')

        # Find compatible vertices in second half
        candidates = []
        for i in range(half, id_counter):
            if (first_mask & adj[i]) == 0:
                candidates.append(i)

        n_cand = len(candidates)
        best2 = 0

        if n_cand <= 20:
            for mask in range(1 << n_cand):
                ok = True
                for i in range(n_cand):
                    if (mask >> i) & 1:
                        vi = candidates[i]
                        for j in range(i + 1, n_cand):
                            if (mask >> j) & 1:
                                vj = candidates[j]
                                if (adj[vi] & (1 << vj)):
                                    ok = False
                                    break
                        if not ok:
                            break
                if ok:
                    best2 = max(best2, bin(mask).count('1'))

        ans = max(ans, cnt1 + best2)

    return str(ans)

