def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        clauses.append(parts[1:])

    # 2-SAT node mapping
    # For variable i (0-indexed): 2*i = x_i is FALSE, 2*i+1 = x_i is TRUE
    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]

    # Build implication graph
    # For each clause, if a literal is false, at least one other literal must be true
    for clause in clauses:
        for i in range(len(clause)):
            lit = clause[i]
            var = abs(lit) - 1

            if lit > 0:
                lit_node = 2 * var + 1  # TRUE
                not_lit = 2 * var       # x is FALSE means not_lit
            else:
                lit_node = 2 * var      # x is FALSE means lit
                not_lit = 2 * var + 1   # not Lit = x is TRUE

            # For all other literals in the clause
            for j in range(i + 1, len(clause)):
                other_lit = clause[j]
                other_var = abs(other_lit) - 1

                if other_lit > 0:
                    other_node = 2 * other_var + 1  # TRUE
                else:
                    other_node = 2 * other_var      # FALSE

                # If not_lit is true, then other_node must be true
                adj[not_lit].append(other_node)

    # Kosaraju's SCC algorithm
    visited = [False] * num_nodes
    order = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    # Build reverse graph
    rev_adj = [[] for _ in range(num_nodes)]
    for u in range(num_nodes):
        for v in adj[u]:
            rev_adj[v].append(u)

    visited = [False] * num_nodes
    comp = [0] * num_nodes
    comp_count = 0

    def dfs2(u, cid):
        visited[u] = True
        comp[u] = cid
        for v in rev_adj[u]:
            if not visited[v]:
                dfs2(v, cid)

    for i in range(num_nodes - 1, -1, -1):
        if not visited[i]:
            dfs2(i, comp_count)
            comp_count += 1

    # Check satisfiability
    for i in range(m):
        node_true = 2 * i + 1
        node_false = 2 * i
        if comp[node_true] == comp[node_false]:
            return "NO"

    # Construct assignment
    assignment = []
    for i in range(m):
        node_true = 2 * i + 1
        node_false = 2 * i
        # If true component has higher ID, assign true
        assignment.append(1 if comp[node_true] > comp[node_false] else 0)

    return "YES" + "".join(map(str, assignment))

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return ""

    n, t = map(int, lines[0].split())
    queries = []
    for line in lines[1:]:
        if line.strip():
            queries.append(tuple(map(int, line.split())))

    results = []
    sx, sy = 0, 0  # Colony starts at origin

    for i, (x, y) in enumerate(queries):
        dx, dy = abs(x - sx), abs(y - sy)
        manhattan = dx + dy
        min_leg = min(dx, dy)
        max_leg = max(dx, dy)

        if manhattan == 0:
            results.append(str(n % 4))
        elif manhattan == 1:
            results.append(str(n // 4))
        else:
            # Manhattan distance >= 2
            # Pattern: depends on n mod 4 and how far
            if n % 4 == 0:
                # For n mod 4 == 0: origin gets 0, neighbors get n//4 each
                # At distance 2 along axis: can reach with count 1 if n large enough
                if min_leg == 0 and max_leg % 2 == 0:
                    # On axis at even distance
                    results.append("1" if max_leg // 2 <= (n // 4 - 1) else "0")
                else:
                    results.append("0")
            else:
                # For n mod 4 != 0
                if min_leg == 0 and manhattan >= 2:
                    results.append("0")
                else:
                    results.append("0")

    return '\n'.join(results)

import math
from functools import lru_cache

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def f(a, b):
    if b == 0:
        return 0
    return 1 + f(a, b - gcd(a, b))

@lru_cache(maxsize=None)
def optimize_f(a, b):
    if b == 0:
        return 0

    if b >= a:
        g = gcd(a, b)
        if g == a:
            return 1 + optimize_f(0, b - a)
        else:
            # Find how many times we can subtract gcd before it changes
            remaining = b
            count = 0
            current_g = gcd(a, b)

            # Number of steps until b changes enough to change gcd
            # We need b mod a to change
            for _ in range(200):  # empirical limit
                # Simulate but use math to skip ahead
                num_atoms = remaining // current_g
                next_b = remaining - num_atoms * current_g
                next_g = gcd(a, next_b)
                if next_g != current_g or next_b == 0:
                    if next_b == 0:
                        count += num_atoms
                        return 1 + count
                    # Actually recalculate with proper approach
                    break

            return optimize_f(a, b - current_g)

    else:
        # For small b, use direct computation
        return 1 + optimize_f(a, b - gcd(a, b))

def solution(s):
    parts = s.strip().split()
    if len(parts) < 2:
        return '0\n'
    x = int(parts[0])
    y = int(parts[1])

    # Optimization: use the mathematical insight
    # In each step we subtract gcd(x, y) from y
    # We continue until y becomes 0

    count = 0
    a, b = x, y

    while b > 0:
        g = gcd(a, b)
        if g == 0:
            break
        # Number of steps until gcd changes or b becomes 0
        # We need to find smallest k > 0 such that gcd(a, b - k*g) != g
        # This happens when b - k*g changes in a way that affects gcd

        # Simple approach: simulate but skip efficiently
        if g <= b:
            steps = b // g
            if b % g == 0:
                steps -= 1  # After steps, b becomes 0
            count += steps
            b = b % g
        else:
            count += 1
            b -= g

    return f"{count}\n"

