def is_gp(sequence):
    """Check if sequence is a geometric progression."""
    n = len(sequence)

    # Single element is always a GP
    if n <= 1:
        return True

    # All zeros case is always a GP
    if all(x == 0 for x in sequence):
        return True

    # If first element is 0 but not all are 0, cannot be a GP
    if sequence[0] == 0:
        return False

    # Calculate ratio from first two elements
    ratio = sequence[1] / float(sequence[0])

    # Check if all consecutive elements follow this ratio
    for i in range(2, n):
        expected = sequence[i-1] * ratio
        if abs(expected - sequence[i]) > 1e-9:
            return False

    return True

