def solution(input_str):
    """
    For each corridor NOT in the MST, output E_max(c) which is the largest energy
    such that if we change the corridor's energy to that value, the edge could
    still be used in an MST.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ""

    edges = []
    for i in range(m):
        a, b, e = map(int, lines[i+1].split())
        edges.append((a-1, b-1, e, i))  # 0-indexed nodes, track original order

    # Kruskal's algorithm to build MST
    parent = list(range(n))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False

    # Sort edges by weight
    sorted_edges = sorted(edges, key=lambda x: x[2])

    mst_set = set()
    tree_adj = [[] for _ in range(n)]

    for a, b, w, idx in sorted_edges:
        if union(a, b):
            mst_set.add(idx)
            tree_adj[a].append((b, w))
            tree_adj[b].append((a, w))

    # BFS to build parent pointers, depths, and edges to parent
    depth = [-1] * n
    parent_node = [-1] * n
    max_edge_to_parent = [0] * n

    queue = [(0, 0) if n > 0 else []]  # (node, depth)
    if n > 0:
        visited = [False] * n
        visited[0] = True
        depth[0] = 0

        while queue:
            u, d = queue.pop(0)
            for v, w in tree_adj[u]:
                if not visited[v]:
                    visited[v] = True
                    depth[v] = d + 1
                    parent_node[v] = u
                    max_edge_to_parent[v] = w
                    queue.append((v, d + 1))

    # Build LCA table for efficient max queries on paths
    LOG = 20
    table = [[-1] * n for _ in range(LOG)]
    max_table = [[0] * n for _ in range(LOG)]

    for i in range(n):
        table[0][i] = parent_node[i]
        max_table[0][i] = max_edge_to_parent[i]

    for i in range(1, LOG):
