def solve_dp(N, A, B):
    if B == 1:
        return "inf"

    def dp(n):
        if n == 0:
            return 1
        res = 0
        for a in range(A + 1):
            if (n - a) % B == 0:
                res = (res + dp((n - a) // B)) % MOD
        return res

    return str(dp(N % B) + dp(N - N % B)) % MOD

