def solution(input_str):
    s = input_str.strip()
    n = len(s)
    i = 0

    def skip_ws():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def parse_number():
        nonlocal i
        skip_ws()
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return s[start:i]

    def parse_term():
        nonlocal i
        skip_ws()
        num_str = parse_number()
        num = int(num_str)

        skip_ws()
        if i < n and s[i] == '-':
            i += 1
            skip_ws()
            num2 = int(parse_number())
            return range_result(num, num2)
        elif i < n and s[i] == '(':
            i += 1
            skip_ws()
            val, length = parse_expr()
            skip_ws()
            if i < n and s[i] == ')':
                i += 1
            return repeat_result(num, val, length)
        else:
            return (int(num_str), len(num_str))

    def parse_expr():
        nonlocal i
        skip_ws()
        if i >= n:
            return (0, 0)
        term1 = parse_term()

        skip_ws()
        while i < n and s[i] == '+':
            i += 1
            term2 = parse_term()
            term1 = concat_mod(term1, term2)
        return term1

    def pow10_mod(x):
        if x == 0:
            return 1
        return pow(10, x, MOD)

    def concat_mod((v1, l1), (v2, l2)):
        return ((v1 * pow10_mod(l2) + v2) % MOD, l2)

    def range_result(start, end):
        val = 0
        length = 0
        for num in range(start, end + 1):
            slen = len(str(num))
            length += slen
            val = (val * pow10_mod(slen) + num) % MOD
        return (val, length)

    def repeat_result(count, val, length):
        if count == 0:
            return (0, 0)
        res = val
        l = length
        for _ in range(count - 1):
            res = (res * pow10_mod(length) + val) % MOD
            l += length
        return (res, l)

    val, _ = parse_expr()
    return str(val) + "\n"

