    def nCr(n_val, r_val):
        """Compute binomial coefficient with overflow check"""
        if r_val < 0 or r_val > n_val:
            return 0
        if r_val == 0 or r_val == n_val:
            return 1
        # Guard against overflow by checking if result would exceed k significantly
        result = 1
        for i in range(min(r_val, n_val - r_val)):
            result = result * (n_val - i) // (i + 1)
            # Early termination if way beyond k (10^18)
            if result > k * 1000:
                return result
        return result

    def max_val_for_i(n, A0, i):
        """Compute max value in A_i, which is always at position n-1 for i >= 1"""
        j = n - 1

        # For i=0, we already checked this above
        total = 0
        for k_pos in range(j + 1):
            coeff = nCr(i + j - k_pos - 1, i - 1)
            if coeff > 0:
                total += A0[k_pos] * coeff  # This could overflow, but we only need comparison
                if total >= k:
                    return k

        return total

    if k == 1:
        # Special case: A₀ might already have 1, or we need to check
        for x in A0:
            if x >= 1:
                return '0\n'
        return '0\n'

    # Search range - exponential growth means i won't be very large
    # For 10^18 with typical growth, should be under 100 iterations
    low, high = 0, 100

    while low < high:
        mid = (low + high) // 2
        if max_val_for_i(n, A0, mid) >= k:
            high = mid
        else:
            low = mid + 1

    return f'{low}\n'

