def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    l, r = map(int, lines[1].split())

    results = []

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return (a * b) // gcd(a, b)

    for x1 in range(1, n + 1):
        found = False
        for x2 in range(x1 + 1, n + 1):
            L = lcm(x1, x2)

            if L > r:
                break  # P must be at least L

            min_P = max(l, L)
            max_P = min(r, m * x1, m * x2)

            if min_P <= max_P:
                P = ((min_P + L - 1) // L) * L
                if P <= max_P:
                    y1 = P // x1
                    y2 = P // x2
                    results.append(f"{x1} {y1} {x2} {y2}")
                    found = True
                    break

        if not found:
            results.append("-1")

    return '\n'.join(results)

