def solution(input_str):
    from functools import lru_cache

    n, k, m = map(int, input_str.strip().split())

    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def dp(mask, current):
        """
        dp[mask][current] = number of ways to visit planets in mask,
        ending at planet 'current', given k planets total needed.
        """
        # Count bits in mask to check if we've visited k planets
        if bin(mask).count('1') == k:
            return 1

        result = 0
        limit = min(n, current + m)

        # Try all possible next positions
        for nxt in range(1, limit + 1):
            # Check if nxt is not yet visited (bit is 0 for position nxt)
            if not (mask & (1 << (nxt - 1))):
                result = (result + dp(mask | (1 << (nxt - 1)), nxt)) % MOD

        return result

    total = 0
    # Try all possible starting planets
    for start in range(1, n + 1):
        total = (total + dp(1 << (start - 1), start)) % MOD

    return str(total)

def nCk(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

