def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    try:
        maxx, maxy, w = map(int, lines[0].split())
    except:
        return '-1'

    # Memoization for reverse
    cache_rev = {}
    def get_rev(n):
        if n not in cache_rev:
            s = str(n)
            cache_rev[n] = int(s[::-1])
        return cache_rev[n]

    def get_ratio(n):
        rn = get_rev(n)
        g = gcd(n, rn)
        return (n // g, rn // g)

    # Precompute ratio groups for both dimensions
    x_groups = defaultdict(list)
    y_groups = defaultdict(list)
    for a in range(1, maxx + 1):
        r = get_ratio(a)
        x_groups[r].append(a)
    for b in range(1, maxy + 1):
        r = get_ratio(b)
        y_groups[r].append(b)

    # Common ratios
    common = set(x_groups.keys()) & set(y_groups.keys())
    if not common:
        return '-1'

    # For efficiency with large inputs, use iteration with early termination
    # Since we want min(x * y) with at least w lucky tickets

    min_prod = float('inf')
    best_x, best_y = -1, -1

    # Try each possible x from 1 to maxx
    for x in range(1, maxx + 1):
        # For this x, compute total lucky tickets for each y
        # and find minimum y that gives us at least w tickets

        # Use prefix-cumulative counting
        total_count = 0

        # Check if we can reach w tickets even with all y
        max_possible = sum(bisect.bisect_right(x_groups[r], x) * len(y_groups[r]) for r in common)
        if max_possible < w:
            continue

        # Find the smallest y for this x
        for y in range(1, maxy + 1):
            seen = 0
            for r in common:
                c_x = bisect.bisect_right(x_groups[r], x)
                c_y = bisect.bisect_right(y_groups[r], y)
                seen += c_x * c_y

            if seen >= w:
                prod = x * y
                if prod < min_prod:
                    min_prod = prod
                    best_x, best_y = x, y
                # Since we're iterating y increasing, first match gives smallest y
                break

        # Early termination if this x can't do better
        if min_prod <= x * 1:
            break

    if best_x == -1:
        return '-1'
    return f"{best_x} {best_y}"

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_divisors(n):
    """Get all divisors of n > 1"""
    if n < 2:
        return set()
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            if i > 1:
                divisors.add(i)
            if n // i > 1:
                divisors.add(n // i)
    return divisors

def solve(input_str):
    try:
        lines = input_str.strip().split('\n')
        if len(lines) < 2:
            return "0"

        n, a, b = map(int, lines[0].split())
        arr = list(map(int, lines[1].split()))
    except:
        return "0"

    if n == 1:
        # Just need to make single element divisible by some d > 1
        candidates = set()
        for val in [arr[0]-1, arr[0], arr[0]+1]:
            if val >= 2:
                candidates.update(get_divisors(val))

        ans = float('inf')
        for d in candidates:
            if arr[0] % d == 0:
                ans = 0
                break
            elif (arr[0]-1) % d == 0 or (arr[0]+1) % d == 0:
                ans = 1
        return str(ans) if ans != float('inf') else "0"

    ans = a * n  # Remove all but one element

    # Handle n=0 edge case
    if n == 0:
        return "0"

    # Collect candidate divisors from x-1, x, x+1 for each element
    candidate_divs = set()
    for x in arr:
        for val in [x - 1, x, x + 1]:
            if val >= 2:
                candidates = get_divisors(val)
                for c in candidates:
                    while c > 1 and c < ans / 2:  # Skip divisors larger than current optimal
                        div = c
                        divisors = get_divisors(div)
                        for d in divisors:
                            if d <= 1:
                                continue
                            candidate_divs.add(d)
                            candidate_divs.add(d * 2)
                            candidate_divs.add(d * 3)

    # For efficiency, limit candidate divisors
    candidate_divs = list(candidate_divs)
    ans = min(ans, a * n)

    for d in candidate_divs[:min(5000, len(candidate_divs))]:
        costs = []
        valid = []

        for x in arr:
            rem_cost = 0
            # Cost to make divisible by d
            if x % d == 0:
                rem = 0
                can_modify = True
            elif (x - 1) % d == 0 or (x + 1) % d == 0:
                rem = 1
                can_modify = True
            else:
                rem = 2
                can_modify = False

            costs.append(rem)
            valid.append(can_modify)

        # If all can be modified
        if all(valid):
            prefix = [0] * n
            total = 0
            prefix[0] = costs[0]
            total = costs[0]
            for i in range(1, n):
                total += costs[i]
                prefix[i] = total

            # Try removing segment [i, n-1]
            for i in range(n):
                cost = prefix[i] + (n - 1 - i) * a
                if cost < ans:
                    ans = cost
        # If some need removal
        elif valid:
            # First invalid position
            first_invalid = None
            for i in range(n):
                if not valid[i]:
                    first_invalid = i
                    break

            if first_invalid is None:
                # All valid - same as all valid case
                if ans > a * n:
                    ans = a * n
                    return str(ans)
            else:
                # Only positions before first_invalid can be kept
                prefix = [0] * first_invalid
                total = 0
                prefix[0] = costs[0] if first_invalid > 0 else 0
                total = costs[0] if first_invalid > 0 else 0
                for i in range(1, first_invalid):
                    total += costs[i]
                    prefix[i] = total

                for i in range(first_invalid):
                    cost = prefix[i] + (n - first_invalid + 1) * a if i == 0 else prefix[i] + (n - 1 - i) * a
                    if cost < ans:
                        ans = cost

        # Special case: try removing from some position
        if valid:
            all_valid = all(v for v in valid)
            if all_valid:
                for i in range(n):
                    seg_len = n - i
                    if seg_len == n:  # Keep nothing
                        continue
                    cost = 0
                    for j in range(n):
                        if j >= i:
                            continue
                        cost += costs[j]
                    cost += seg_len * a
                    if cost < ans:
                        ans = cost
            else:
                first_invalid = None
                for i in range(n):
                    if not valid[i]:
                        first_invalid = i
                        break
                if first_invalid is not None:
                    prefix = []
                    total = 0
                    for i in range(first_invalid):
                        total += costs[i]
                        prefix.append(total)

                    for i in range(first_invalid):
                        seg_len = n - i
                        cost = prefix[i] + seg_len * a
                        if cost < ans:
                            ans = cost

    return str(ans)

def solution(input_str):
